import React, { useState } from "react";
import Register from "./Register";
import Login from "./Login";
import ForgotPassword from "./ForgotPassword";
import LandingPage from "./LandingPage";
import CustomerDashboard from "./CustomerDashboard";

function App() {
  const [currentPage, setCurrentPage] = useState("landing");
  const [selectedRole, setSelectedRole] = useState("customer");
  const [isCustomerLoggedIn, setIsCustomerLoggedIn] = useState(false);

  const handleLoginSuccess = (role) => {
    if (role === "customer") {
      setIsCustomerLoggedIn(true);
      setCurrentPage("dashboard");
    }
  };

  const handleLogout = () => {
    setIsCustomerLoggedIn(false);
    setSelectedRole("customer");
    setCurrentPage("landing");
  };

  if (currentPage === "login") {
    return (
      <Login
        role={selectedRole}
        onLoginSuccess={handleLoginSuccess}
        onRoleChange={setSelectedRole}
        onRegisterClick={() => setCurrentPage("register")}
        onForgotPasswordClick={() => setCurrentPage("forgot")}
        onLandingClick={() => setCurrentPage("landing")}
      />
    );
  }

  if (currentPage === "forgot") {
    return <ForgotPassword role={selectedRole} onBackToLogin={() => setCurrentPage("login")} />;
  }

  if (currentPage === "register") {
    return (
      <Register
        role={selectedRole}
        onRoleChange={setSelectedRole}
        onLoginClick={() => setCurrentPage("login")}
        onLandingClick={() => setCurrentPage("landing")}
      />
    );
  }

  if (currentPage === "dashboard" && isCustomerLoggedIn) {
    return <CustomerDashboard onLogout={handleLogout} />;
  }

  return (
    <LandingPage
      onLoginClick={() => setCurrentPage("login")}
      onRegisterClick={() => {
        setSelectedRole("customer");
        setCurrentPage("register");
      }}
    />
  );
}

export default App;
